import {api} from './workspace-shared.js';

export function createTranscriptSummary() {
  const button=document.createElement('button');button.type='button';button.className='teacher-button secondary';button.textContent='Summarise a transcript';
  document.querySelector('.teacher-heading .teacher-actions').append(button);
  const dialog=document.createElement('dialog');dialog.className='transcript-summary';dialog.setAttribute('aria-labelledby','transcript-summary-title');
  dialog.innerHTML=`<button type="button" class="teacher-close" aria-label="Close transcript summary">×</button><p class="teacher-eyebrow">OPENAI TRANSCRIPT TEST</p><h2 id="transcript-summary-title">Summarise a lesson transcript</h2><p>Upload a .txt or .vtt file to ask OpenAI for a class summary. The full transcript is sent to OpenAI when you generate. The transcript and summary are not saved to your classes or shared with students.</p><form><label for="summary-transcript-file">Lesson transcript (up to 512 KiB)</label><input id="summary-transcript-file" type="file" accept=".txt,.vtt,text/plain,text/vtt" required><button class="teacher-button" type="submit">Generate class summary</button></form><p data-transcript-status role="status" aria-live="polite"></p><p data-transcript-error role="alert" hidden></p><section data-transcript-result hidden><h3>OpenAI class summary · teacher review draft</h3><p data-transcript-metadata></p><div class="transcript-summary-output"></div><button type="button" class="teacher-button secondary" data-transcript-download>Download API summary</button></section>`;
  document.body.append(dialog);
  const $=s=>dialog.querySelector(s);let epoch=0,result=null;
  button.onclick=()=>dialog.showModal();
  $('.teacher-close').onclick=()=>dialog.close();
  dialog.addEventListener('close',()=>{epoch++;result=null;$('form').reset();$('[data-transcript-result]').hidden=true;$('.transcript-summary-output').textContent='';$('[data-transcript-status]').textContent='';$('[data-transcript-error]').hidden=true;for(const c of dialog.querySelectorAll('input,button'))c.disabled=false;button.focus();});
  $('form').onsubmit=async event=>{
    event.preventDefault();const file=$('input').files[0];if(!file)return;
    const error=$('[data-transcript-error]');error.hidden=true;
    if(file.size>524288 || file.size<30){error.textContent='Choose a transcript between 30 bytes and 512 KiB.';error.hidden=false;return;}
    const token=++epoch;$('[data-transcript-result]').hidden=true;result=null;
    $('input').disabled=true;$('[type=submit]').disabled=true;
    $('[data-transcript-status]').textContent='Uploading the complete transcript to OpenAI and creating a summary… This may take up to 90 seconds.';
    try{
      const encoded=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('Could not read this file.'));reader.readAsDataURL(file);});
      if(token!==epoch)return;
      const response=await api('/api/teacher/transcript-summary',{filename:file.name,fileData:'data:text/plain;base64,'+encoded},{timeoutMs:100000});
      if(token!==epoch)return;result=response;
      $('.transcript-summary-output').textContent=result.summary;
      $('[data-transcript-metadata]').textContent=`${result.provider} · ${result.model} · full file: ${result.inputBytes.toLocaleString()} bytes${result.usage?' · '+result.usage.totalTokens.toLocaleString()+' tokens':''} · Request: ${result.requestId || result.responseId || 'completed'}`;
      $('[data-transcript-result]').hidden=false;$('[data-transcript-status]').textContent='Real OpenAI API response received. Review the summary before using it.';
      $('[data-transcript-result]').scrollIntoView({block:'start'});
    }catch(e){if(token!==epoch)return;error.textContent=e.message;error.hidden=false;$('[data-transcript-status]').textContent='No summary was saved.';}
    finally{if(token===epoch){$('input').disabled=false;$('[type=submit]').disabled=false;}}
  };
  $('[data-transcript-download]').onclick=()=>{
    if(!result)return;const text=result.summary+`\n\n---\nGenerated by the OpenAI API\nModel: ${result.model}\nRequest: ${result.requestId || ''}\nResponse: ${result.responseId || ''}\nInput bytes: ${result.inputBytes}\nUsage: ${JSON.stringify(result.usage)}\n`;
    const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='inkwire-openai-class-summary.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
  };
}
